        second_port = reserved.getsockname()[1]
        reserved.listen()
        first_reservation.close()

        routes = [
            (first_port, 18080, 1, 85000, "unused"),
            (second_port, 18081, 1, 132000, "unused"),
        ]
        with mock.patch.object(proxy, "ROUTES", routes):
            with mock.patch.object(proxy.AutoTokenizer, "from_pretrained", return_value=object()):
                with self.assertRaises(SystemExit) as raised:
                    await proxy.main()

        reserved.close()
        self.assertEqual(raised.exception.code, 78)

        probe = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        try:
            probe.bind(("127.0.0.1", first_port))
        finally:
            probe.close()

