#!/usr/bin/env python3
"""Reverse proxy enforcing per-model concurrency limits + token budget in
front of the MLX model servers.

mlx_vlm.server has no concurrency cap of its own -- continuous batching
admits every request that arrives, which is how the former 35B-A3B server hit
71GB of KV cache before --max-kv-size existed (see PLAN.md). This sits on
the ports clients already use (8080/8081) and forwards to the real
servers on internal ports (18080/18081), gating concurrent POST requests
with a semaphore per upstream so callers queue instead of stacking up
unbounded KV caches. GET requests (/health, /v1/models) bypass the
semaphore so monitoring isn't blocked behind a saturated generation queue.

Also counts prompt tokens on POST /v1/chat/completions using each model's
own tokenizer (not an approximation) and hard-rejects requests that would
land within 10% of the upstream's --max-kv-size budget, rather than
letting them hit the model server's silent RotatingKVCache middle-eviction.
See proxy-token-compaction-plan.md for the reasoning.
"""
import asyncio
import json
import logging
import os
import socket
import threading
import time
import uuid

from aiohttp import ClientError, ClientSession, ClientTimeout, web
from transformers import AutoTokenizer

try:
    from scripts.proxy_config import (
        DEFAULT_MAX_BODY_BYTES,
        DEFAULT_MAX_TOKENS,
        DEFAULT_MULTIMODAL_MAX_OUTPUT_TOKENS,
        MODELS_DIR,
        build_routes,
    )
except ImportError:  # Running this file directly from scripts/.
    from proxy_config import (  # type: ignore[no-redef]
        DEFAULT_MAX_BODY_BYTES,
        DEFAULT_MAX_TOKENS,
        DEFAULT_MULTIMODAL_MAX_OUTPUT_TOKENS,
        MODELS_DIR,
        build_routes,
    )

logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")
log = logging.getLogger("kv_proxy")

# One JSON line per completed chat request: prompt/completion token counts,
# used by scripts/token_savings.py to estimate $ saved vs a cloud API.
TOKEN_LOG_PATH = os.path.expanduser("~/code/ai-stack/logs/token_usage.jsonl")

_build_routes = build_routes
ROUTES = _build_routes()

# Fraction of (max_kv_size - effective_max_tokens) beyond which a request
# is rejected instead of forwarded -- see "Enforcement at 90%" in the plan.
BUDGET_THRESHOLD = 0.9

# How long a request may sit waiting for the per-model semaphore before
# giving up with a 503 instead of queueing forever behind a stalled or
# just-slow generation.
# Fail queued requests promptly when both 27B generation slots are busy.
QUEUE_TIMEOUT_S = 60

# Ceiling on one request's total time holding the semaphore (upstream
# generation + streaming the response back to the client). Matches the
# servers' own MLX_VLM_TOKEN_QUEUE_TIMEOUT (1800s) so this never clips a
# legitimate long generation -- it exists to force-release the semaphore
# if the *downstream* client stops reading (backgrounded tab, dead
# process), which would otherwise hold the slot open indefinitely since
# response.write() blocks on TCP backpressure with no timeout of its own.
REQUEST_TIMEOUT_S = 1800
MAX_BODY_BYTES = int(os.environ.get("PROXY_MAX_BODY_BYTES") or DEFAULT_MAX_BODY_BYTES)
MULTIMODAL_MAX_OUTPUT_TOKENS = int(
    os.environ.get("PROXY_MULTIMODAL_MAX_OUTPUT_TOKENS") or DEFAULT_MULTIMODAL_MAX_OUTPUT_TOKENS
)
ACCOUNTING_TEXT_LIMIT = 2 * 1024 * 1024
PROXY_BIND_HOST = os.environ.get("PROXY_BIND_HOST", "127.0.0.1")

STRIPPED_HEADERS = {
    "connection",
    "content-encoding",
    "content-length",
    "host",
    "keep-alive",
    "proxy-authenticate",
    "proxy-authorization",
    "te",
    "trailer",
    "transfer-encoding",
    "upgrade",
}


def filter_proxy_headers(headers) -> dict[str, str]:
    """Remove hop-by-hop headers, including names listed by Connection."""
    if hasattr(headers, "getall"):
        connection_values = headers.getall("Connection", [])
    else:
        connection = headers.get("Connection")
        connection_values = [connection] if connection else []
    connection_headers = {
        name.strip().lower()
        for value in connection_values
        for name in value.split(",")
        if name.strip()
    }
    stripped = STRIPPED_HEADERS | connection_headers
    return {key: value for key, value in headers.items() if key.lower() not in stripped}


def is_multimodal(messages: list) -> bool:
    """True if any message content contains an image part. Vision tokens
    aren't visible to the text tokenizer, so counting is untrustworthy
    for these requests -- see plan's "known blind spot"."""
    for msg in messages:
        content = msg.get("content")
        if isinstance(content, list):
            for part in content:
                if isinstance(part, dict) and part.get("type") in (
                    "image_url",
                    "image",
                    "input_image",
                ):
                    return True
    return False


def count_prompt_tokens(tokenizer, messages: list, tools) -> int:
    # return_dict=False: without it, apply_chat_template(tokenize=True)
    # returns {"input_ids": [...], "attention_mask": [...]} and len()
    # silently counts dict keys (2) instead of tokens.
    # Match mlx_vlm.server's normalization before Qwen's template iterates
    # tool arguments with Jinja's |items filter.
    normalized_messages = []
    for message in messages:
        normalized_message = dict(message)
        tool_calls = message.get("tool_calls")
        if tool_calls is not None:
            normalized_calls = []
            for tool_call in tool_calls:
                normalized_call = dict(tool_call)
                function = dict(normalized_call.get("function") or {})
                arguments = function.get("arguments")
                if isinstance(arguments, str):
                    try:
                        function["arguments"] = json.loads(arguments)
                    except json.JSONDecodeError:
                        function["arguments"] = {}
                normalized_call["function"] = function
                normalized_calls.append(normalized_call)
            normalized_message["tool_calls"] = normalized_calls
        normalized_messages.append(normalized_message)

    kwargs = {"add_generation_prompt": True, "tokenize": True, "return_dict": False}
    if tools:
        kwargs["tools"] = tools
    token_ids = tokenizer.apply_chat_template(normalized_messages, **kwargs)
    return len(token_ids)


def extract_completion(raw: bytes) -> tuple[int | None, str]:
    """Returns (completion_tokens_reported_by_server_or_None, completion_text).
    Handles both a single non-streaming JSON body and an SSE stream of
    "data: {...}" chunks. Never raises -- worst case returns (None, "")."""
    try:
        text = raw.decode("utf-8", errors="ignore").strip()
    except Exception:
        return None, ""
    if not text:
        return None, ""

    if text.startswith("{"):
        try:
            obj = json.loads(text)
        except json.JSONDecodeError:
            return None, ""
        usage = obj.get("usage") or {}
        choices = obj.get("choices") or []
        pieces = []
        if choices:
            msg = choices[0].get("message") or {}
            _collect_generated_text(msg, pieces)
        return usage.get("completion_tokens"), "".join(pieces)

    pieces = []
    usage_tokens = None
    for line in text.split("\n"):
        line = line.strip()
        if not line.startswith("data:"):
            continue
        payload = line[len("data:"):].strip()
        if payload == "[DONE]":
            continue
        try:
            obj = json.loads(payload)
        except json.JSONDecodeError:
            continue
        usage = obj.get("usage")
        if usage and usage.get("completion_tokens") is not None:
            usage_tokens = usage["completion_tokens"]
        choices = obj.get("choices") or []
        if choices:
            _collect_generated_text(choices[0].get("delta") or {}, pieces)
    return usage_tokens, "".join(pieces)


def _collect_generated_text(msg_or_delta: dict, pieces: list) -> None:
    """Appends every piece of model-generated text in a message/delta object
    to `pieces` -- content, thinking (reasoning_content), and tool-call
    arguments -- so a tool-call-only or thinking-only turn still counts
    toward completion_tokens instead of silently logging as empty."""
    content = msg_or_delta.get("content")
    if content:
        pieces.append(content)
    reasoning = msg_or_delta.get("reasoning_content") or msg_or_delta.get("reasoning")
    if reasoning:
        pieces.append(reasoning)
    for call in msg_or_delta.get("tool_calls") or []:
        args = (call.get("function") or {}).get("arguments")
        if args:
            pieces.append(args)


def log_token_usage(model_path: str, prompt_tokens: int, completion_tokens: int) -> None:
    entry = {
        "ts": time.time(),
        "model": os.path.basename(model_path),
        "prompt_tokens": prompt_tokens,
        "completion_tokens": completion_tokens,
    }
    try:
        with open(TOKEN_LOG_PATH, "a") as f:
            f.write(json.dumps(entry) + "\n")
    except OSError as e:
        log.warning("failed to write token usage log: %s", e)


class CompletionAccounting:
    """Parse usage while streaming without retaining the whole response."""

    def __init__(self, stream: bool):
        self.stream = stream
        self.buffer = b""
        self.raw_chunks: list[bytes] = []
        self.raw_bytes = 0
        self.text: list[str] = []
        self.text_bytes = 0
        self.usage_tokens: int | None = None
        self.truncated = False

    def feed(self, chunk: bytes) -> None:
        if not self.stream:
            if self.raw_bytes < ACCOUNTING_TEXT_LIMIT:
                limited = chunk[: ACCOUNTING_TEXT_LIMIT - self.raw_bytes]
                self.raw_chunks.append(limited)
                self.raw_bytes += len(limited)
                if len(limited) < len(chunk):
                    self.truncated = True
            else:
                self.truncated = True
            return
        self.buffer += chunk
        if len(self.buffer) > ACCOUNTING_TEXT_LIMIT:
            self.buffer = self.buffer[-ACCOUNTING_TEXT_LIMIT:]
            self.truncated = True
        while b"\n" in self.buffer:
            line, self.buffer = self.buffer.split(b"\n", 1)
            self._feed_sse_line(line)

    def finish(self) -> None:
        if self.stream and self.buffer:
            self._feed_sse_line(self.buffer)

    def _feed_sse_line(self, raw_line: bytes) -> None:
        line = raw_line.strip()
        if not line.startswith(b"data:"):
            return
        payload = line[5:].strip()
        if payload == b"[DONE]":
            return
        try:
            obj = json.loads(payload)
        except (json.JSONDecodeError, UnicodeDecodeError):
            return
        usage = obj.get("usage") or {}
        if usage.get("completion_tokens") is not None:
            self.usage_tokens = usage["completion_tokens"]
        choices = obj.get("choices") or []
        if choices and self.text_bytes <= ACCOUNTING_TEXT_LIMIT:
            pieces: list[str] = []
            _collect_generated_text((choices[0].get("delta") or {}), pieces)
            for piece in pieces:
                encoded = piece.encode("utf-8")
                if self.text_bytes + len(encoded) > ACCOUNTING_TEXT_LIMIT:
                    self.truncated = True
                    return
                self.text.append(piece)
                self.text_bytes += len(encoded)

    def result(self) -> tuple[int | None, str]:
        self.finish()
        if self.stream:
            return self.usage_tokens, "" if self.truncated else "".join(self.text)
        return extract_completion(b"".join(self.raw_chunks))


def make_app(upstream_port: int, limit: int, max_kv_size: int, model_path: str) -> web.Application:
    semaphore = asyncio.Semaphore(limit)
    session: ClientSession | None = None
    tokenizer = None
    tokenizer_lock = threading.Lock()
    usage_log_lock = asyncio.Lock()
    stats = {
        "active": 0,
        "completed": 0,
        "rejected": 0,
        "queue_timeouts": 0,
        "upstream_errors": 0,
        "request_timeouts": 0,
    }

    async def on_startup(app):
        nonlocal session, tokenizer
        session = ClientSession(timeout=ClientTimeout(total=None, sock_connect=10, sock_read=None))
        log.info("loading tokenizer for %s (:%d)...", model_path, upstream_port)
        tokenizer = AutoTokenizer.from_pretrained(model_path)
        log.info("tokenizer ready for :%d", upstream_port)

    async def on_cleanup(app):
        if session is not None:
            await session.close()

    def check_budget(body: bytes) -> tuple[bool, str, int | None, int, str]:
        """Returns (allowed, message, prompt_tokens, status, reason)."""
        try:
            payload = json.loads(body)
        except (json.JSONDecodeError, UnicodeDecodeError) as e:
            return False, f"invalid JSON: {e}", None, 400, "invalid_json"

        if not isinstance(payload, dict):
            return False, "request body must be a JSON object", None, 400, "invalid_schema"

        requested_model = payload.get("model")
        if requested_model != model_path:
            return (
                False,
                f"model must be {model_path!r}; received {requested_model!r}",
                None,
                400,
                "model_mismatch",
            )

        messages = payload.get("messages")
        if not messages:
            return False, "messages must be a non-empty list", None, 400, "invalid_schema"
        if not isinstance(messages, list) or not all(isinstance(message, dict) for message in messages):
            return False, "messages must be a list of objects", None, 400, "invalid_schema"

        if is_multimodal(messages):
            max_tokens = payload.get("max_tokens") or payload.get("max_output_tokens") or DEFAULT_MAX_TOKENS
            if not isinstance(max_tokens, int) or max_tokens < 0:
                return False, "max_tokens must be a non-negative integer", None, 400, "invalid_schema"
            if max_tokens > MULTIMODAL_MAX_OUTPUT_TOKENS:
                return False, (
                    f"multimodal requests are limited to {MULTIMODAL_MAX_OUTPUT_TOKENS} output tokens"
                ), None, 400, "multimodal_budget_unknown"
            return True, "multimodal request admitted under conservative output cap", None, 200, "multimodal"

        max_tokens = payload.get("max_tokens") or payload.get("max_output_tokens") or DEFAULT_MAX_TOKENS
        if not isinstance(max_tokens, int) or max_tokens < 0:
            return False, "max_tokens must be a non-negative integer", None, 400, "invalid_schema"

        try:
            with tokenizer_lock:
                prompt_tokens = count_prompt_tokens(tokenizer, messages, payload.get("tools"))
        except Exception as e:
            return False, f"token counting unavailable: {e}", None, 503, "tokenizer_unavailable"

        budget = max_kv_size - max_tokens
        if budget <= 0:
            return False, "max_tokens exceeds the model KV budget", prompt_tokens, 400, "invalid_budget"
        threshold = BUDGET_THRESHOLD * budget
        msg = (
            f"prompt_tokens={prompt_tokens} max_tokens={max_tokens} "
            f"budget={budget} threshold={threshold:.0f} max_kv_size={max_kv_size}"
        )
        if prompt_tokens > threshold:
            return False, msg, prompt_tokens, 400, "context_length_budget_exceeded"
        return True, msg, prompt_tokens, 200, "allowed"

    async def handle(request: web.Request) -> web.StreamResponse:
        request_id = request.headers.get("X-Request-ID", uuid.uuid4().hex)
        started_at = time.monotonic()
        # The upstream may enumerate cached models. Each route has one
        # configured model, so expose only the model actually served here.
        if request.method == "GET" and request.path == "/v1/models":
            return web.json_response(
                {
                    "object": "list",
                    "data": [{"id": model_path, "object": "model", "created": int(time.time())}],
                }
            )
        if request.method == "GET" and request.path == "/proxy/health":
            return web.json_response({"status": "ok", "upstream_port": upstream_port, **stats})

        upstream_url = f"http://127.0.0.1:{upstream_port}{request.path_qs}"
        headers = filter_proxy_headers(request.headers)
        gated = request.method != "GET"
        is_chat_completions = request.method == "POST" and request.path == "/v1/chat/completions"

        body = None
        prompt_tokens = None
        if request.method not in {"GET", "HEAD"}:
            if request.content_length is not None and request.content_length > MAX_BODY_BYTES:
                stats["rejected"] += 1
                return web.json_response(
                    {"error": {"message": "request body too large", "type": "request_too_large"}}, status=413
                )
            try:
                body = await request.read()
            except web.HTTPRequestEntityTooLarge:
                stats["rejected"] += 1
                return web.json_response(
                    {"error": {"message": "request body too large", "type": "request_too_large"}}, status=413
                )

        if is_chat_completions:
            allowed, log_msg, prompt_tokens, budget_status, budget_reason = await asyncio.to_thread(
                check_budget, body
            )
            log.info("%s :%d %s", "REJECT" if not allowed else "OK", upstream_port, log_msg)
            if not allowed:
                stats["rejected"] += 1
                guidance = (
                    ". Reduce prompt size or start a new session."
                    if budget_reason == "context_length_budget_exceeded"
                    else ""
                )
                return web.json_response(
                    {
                        "error": {
                            "message": f"Request rejected: {log_msg}{guidance}",
                            "type": budget_reason,
                        }
                    }, status=budget_status,
                )

        queue_started = time.monotonic()
        if gated:
            try:
                await asyncio.wait_for(semaphore.acquire(), timeout=QUEUE_TIMEOUT_S)
            except asyncio.TimeoutError:
                stats["queue_timeouts"] += 1
                log.warning("queue timeout after %ds, upstream :%d busy", QUEUE_TIMEOUT_S, upstream_port)
                return web.json_response(
                    {"error": {"message": "Server busy, try again shortly.", "type": "queue_timeout"}},
                    status=503,
                )
        # Populated by _proxy_once once it has sent headers, so the timeout
        # handler below can tell whether a response is already in flight on
        # the wire -- returning a *second* response object for the same
        # request silently corrupts the stream instead of raising, and if
        # the client is the reason we're stalled, writing that second
        # response hangs forever in aiohttp's drain() (see PLAN.md).
        started = {"response": None, "raw": b""}
        stats["active"] += 1
        stats["queue_wait_seconds"] = round(time.monotonic() - queue_started, 3)
        try:
            result = await asyncio.wait_for(
                _proxy_once(request, upstream_url, headers, body, started), timeout=REQUEST_TIMEOUT_S
            )
            if is_chat_completions and prompt_tokens is not None:
                usage_tokens, completion_text = started["accounting"].result()
                completion_tokens = usage_tokens
                if completion_tokens is None and completion_text:
                    try:
                        completion_tokens = len(tokenizer.encode(completion_text))
                    except Exception as e:
                        log.warning("completion token count failed: %s", e)
                if completion_tokens is not None:
                    async with usage_log_lock:
                        await asyncio.to_thread(log_token_usage, model_path, prompt_tokens, completion_tokens)
            stats["completed"] += 1
            return result
        except asyncio.TimeoutError:
            stats["request_timeouts"] += 1
            log.warning("request timeout after %ds, force-releasing :%d slot", REQUEST_TIMEOUT_S, upstream_port)
            if started["response"] is not None:
                # Headers already sent to the client -- can't switch to a
                # fresh response. Kill the transport so aiohttp finishes
                # the in-flight one with a clean ConnectionError instead of
                # hanging in drain() on a stalled client.
                if request.transport is not None:
                    request.transport.close()
                return started["response"]
            return web.json_response(
                {"error": {"message": "Request exceeded time limit.", "type": "request_timeout"}},
                status=504,
            )
        except (ClientError, ConnectionError) as error:
            stats["upstream_errors"] += 1
            log.warning("request %s upstream error on :%d: %s", request_id, upstream_port, error)
            if started["response"] is not None and request.transport is not None:
                request.transport.close()
                return started["response"]
            return web.json_response(
                {"error": {"message": "Upstream unavailable.", "type": "upstream_unavailable"}}, status=502
            )
        finally:
            stats["active"] -= 1
            log.info("request=%s upstream=:%d duration=%.3fs", request_id, upstream_port, time.monotonic() - started_at)
            if gated:
                semaphore.release()

    async def _proxy_once(
        request: web.Request, upstream_url: str, headers: dict, body, started: dict
    ) -> web.StreamResponse:
        data = body if body is not None else request.content
        stream = False
        if body is not None:
            try:
                stream = bool(json.loads(body).get("stream"))
            except (json.JSONDecodeError, AttributeError):
                pass
        async with session.request(
            request.method, upstream_url, headers=headers, data=data
        ) as upstream_resp:
            resp_headers = filter_proxy_headers(upstream_resp.headers)
            response = web.StreamResponse(
                status=upstream_resp.status, headers=resp_headers
            )
            await response.prepare(request)
            started["response"] = response
            accounting = CompletionAccounting(stream=stream)
            started["accounting"] = accounting
            async for chunk in upstream_resp.content.iter_any():
                await response.write(chunk)
                accounting.feed(chunk)
            await response.write_eof()
            accounting.finish()
            return response

    app = web.Application(client_max_size=MAX_BODY_BYTES)
    app.on_startup.append(on_startup)
    app.on_cleanup.append(on_cleanup)
    app.router.add_route("*", "/{path:.*}", handle)
    return app


async def main():
    sockets = []
    runners = []
    try:
        # Reserve every public port before loading tokenizers or starting an
        # aiohttp site. This prevents a partial startup where :8080 is live
        # but :8081 fails, and closes all reservations on any bind error.
        for listen_port, *_ in ROUTES:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            try:
                sock.bind((PROXY_BIND_HOST, listen_port))
                sock.listen(socket.SOMAXCONN)
            except OSError as error:
                sock.close()
                raise RuntimeError(
                    f"cannot bind proxy port {listen_port}; "
                    "another process may already be using it"
                ) from error
            sockets.append(sock)

        prepared = []
        for route, sock in zip(ROUTES, sockets):
            _, upstream_port, limit, max_kv_size, model_path = route
            app = make_app(upstream_port, limit, max_kv_size, model_path)
            runner = web.AppRunner(app)
            runners.append(runner)
            await runner.setup()
            prepared.append((route, sock, runner))

        # Load every tokenizer and initialize every app before exposing any
        # public listener. A failed second route must not leave the first one
        # serving with a half-started configuration.
        for route, sock, runner in prepared:
            listen_port, upstream_port, limit, max_kv_size, _ = route
            site = web.SockSite(runner, sock)
            await site.start()
            log.info(
                "listening on :%d -> 127.0.0.1:%d (concurrency=%d, max_kv_size=%d)",
                route[0],
                upstream_port,
                limit,
                max_kv_size,
            )

        await asyncio.Event().wait()
    except RuntimeError as error:
        log.error("proxy startup failed: %s", error)
        raise SystemExit(78) from error
    finally:
        for runner in runners:
            await runner.cleanup()
        for sock in sockets:
            sock.close()


if __name__ == "__main__":
    asyncio.run(main())

