def sse(*objects: dict) -> bytes:
    lines = [f"data: {json.dumps(obj)}" for obj in objects]
    return ("\n".join(lines) + "\ndata: [DONE]\n").encode()


class ExtractCompletionTests(unittest.TestCase):
    def test_stream_collects_reasoning_and_incremental_tool_arguments(self):
        raw = sse(
            {"choices": [{"delta": {"reasoning_content": "Use weather. "}}]},
            {
                "choices": [
                    {
                        "delta": {
                            "tool_calls": [
                                {"function": {"arguments": '{"city":'}}
                            ]
                        }
                    }
                ]
            },
            {
                "choices": [
                    {
                        "delta": {
                            "tool_calls": [
                                {"function": {"arguments": '"Chicago"}'}}
                            ]
                        }
                    }
                ]
            },
        )

        self.assertEqual(
            proxy.extract_completion(raw),
            (None, 'Use weather. {"city":"Chicago"}'),
        )

    def test_tool_only_stream_is_not_empty(self):
        raw = sse(
            {
                "choices": [
                    {
                        "delta": {
                            "tool_calls": [
                                {"function": {"arguments": "{}"}}
                            ]
                        }
                    }
                ]
            }
        )

        self.assertEqual(proxy.extract_completion(raw), (None, "{}"))

    def test_server_usage_takes_precedence(self):
        raw = sse(
            {"choices": [{"delta": {"reasoning_content": "Think"}}]},
            {"choices": [], "usage": {"completion_tokens": 17}},
        )

        self.assertEqual(proxy.extract_completion(raw), (17, "Think"))

    def test_non_streaming_collects_all_generated_fields(self):
        raw = json.dumps(
            {
                "choices": [
                    {
                        "message": {
                            "reasoning_content": "Think. ",
                            "content": "Answer. ",
                            "tool_calls": [
                                {"function": {"arguments": '{"ok":true}'}}
                            ],
                        }
                    }
                ]
            }
        ).encode()

        self.assertEqual(
            proxy.extract_completion(raw),
            (None, 'Answer. Think. {"ok":true}'),
        )


class TimeoutTransportTests(unittest.IsolatedAsyncioTestCase):
    async def test_timeout_after_headers_tolerates_missing_transport(self):
        response = object()

        async def force_timeout(awaitable, timeout):
            started = awaitable.cr_frame.f_locals["started"]
            started["response"] = response
            awaitable.close()
            raise asyncio.TimeoutError

        request = SimpleNamespace(
            content=None,
            headers={},
            method="GET",
            path="/health",
            path_qs="/health",
            transport=None,
        )
        app = proxy.make_app(18080, 1, 85000, "unused")
        handler = next(iter(app.router.routes())).handler

        with mock.patch.object(proxy.asyncio, "wait_for", new=force_timeout):
            result = await handler(request)

        self.assertIs(result, response)


